using System;
using System.Collections.Generic;
using System.IO;
using System.IO.Compression;
using System.Text;

namespace Naufal_Windows_Tech_s_Powertoys;

// Generated from literal reference language tables plus the native toolbar keys.
// Regenerate data with Tests/ParityAudit/Export-SupplementalTranslations.ps1.
internal static class SupplementalUiCatalog
{
    internal static void Merge(Dictionary<string, Dictionary<string, string>> catalog)
    {
        using MemoryStream source = new(Convert.FromBase64String(Data));
        using GZipStream gzip = new(source, CompressionMode.Decompress);
        using BinaryReader reader = new(gzip, Encoding.UTF8);
        int languages = reader.ReadInt32();
        for (int i = 0; i < languages; i++)
        {
            string code = reader.ReadString();
            int count = reader.ReadInt32();
            if (!catalog.TryGetValue(code, out var table))
                catalog[code] = table = new(StringComparer.OrdinalIgnoreCase);
            for (int j = 0; j < count; j++) { string key = reader.ReadString(); table[key] = reader.ReadString(); }
        }
    }
